+// summaryLimit is how many characters of the actual output the mismatch summary shows.
+const summaryLimit = 120
+
+// actualSummary leads every feasibility mismatch line: the actual exit code, the start of the
+// actual output on one line, and the exit code the declaration expected.
+func actualSummary(actual CheckResult, wantExit int) string {
+	text := strings.NewReplacer("\r\n", " ", "\n", " ", "\r", " ").Replace(strings.TrimRight(actual.Output, "\r\n"))
+	if text == "" {
+		text = "(no output)"
+	} else if r := []rune(text); len(r) > summaryLimit {
+		text = string(r[:summaryLimit]) + "[cut]"
+	}
+	return fmt.Sprintf("actual exit %d: %s (expected exit %d)", actual.Exit, text, wantExit)
+}
+
 func withTimedOut(m map[string]any) map[string]any {
 	c := shallowCopy(m)
 	c["timed_out"] = false

